export const DEMO_USERS = [
  DAVE, ERIN, FRANK, GRACE, HENRY, IVY, JACK, KATE, LEO, MIA,
  NICK, OLIVIA, PAUL, QUINN, RYAN, SARA, TOM, UMA, VICTOR, WENDY,
];

function top(user, time, content, { up = 0, view = 0 } = {}, replies = []) {
  return { user, time: `${time}:00`, content, up, view, replies };
}

function re(user, time, content, { to, up = 0 } = {}) {
  return { user, time: `${time}:00`, content, to, up };
}

